import Database from 'better-sqlite3'
import path from 'node:path'

const DB_PATH = path.resolve(import.meta.dirname, '..', 'blog.db')

let db: Database.Database | null = null

export function getDb(): Database.Database {
  if (!db) {
    db = new Database(DB_PATH)
    db.pragma('journal_mode = WAL')
    initializeDb(db)
  }
  return db
}

function initializeDb(db: Database.Database): void {
  db.exec(`
    CREATE TABLE IF NOT EXISTS posts (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      title TEXT NOT NULL,
      content TEXT NOT NULL
    )
  `)
}

export interface Post {
  id: number
  title: string
  content: string
}

import { createServerFn } from '@tanstack/react-start'
import { getDb } from '../db'
import type { Post } from '../db'

export const getPosts = createServerFn({ method: 'GET' }).handler(async (): Promise<Post[]> => {
  const db = getDb()
  const posts = db.prepare('SELECT id, title, content FROM posts ORDER BY id DESC').all() as Post[]
  return posts
})

export const getPostById = createServerFn({ method: 'GET' })
  .validator((data: unknown) => {
    const id = typeof data === 'number' ? data : Number(data)
    if (isNaN(id) || id < 1) {
      throw new Error('Invalid post ID')
    }
    return id
  })
  .handler(async ({ data: id }): Promise<Post | null> => {
    const db = getDb()
    const post = db.prepare('SELECT id, title, content FROM posts WHERE id = ?').get(id) as Post | undefined
    return post ?? null
  })

import { createFileRoute, Link } from '@tanstack/react-router'
import { getPosts } from '../server-functions/posts'

export const Route = createFileRoute('/')({
  loader: async () => {
    const posts = await getPosts()
    return { posts }
  },
  component: Home,
})

function Home() {
  const { posts } = Route.useLoaderData()

  return (
    <main className="page-wrap px-4 pb-8 pt-14">
      <section className="island-shell rise-in relative overflow-hidden rounded-[2rem] px-6 py-10 sm:px-10 sm:py-14">
        <div className="pointer-events-none absolute -left-20 -top-24 h-56 w-56 rounded-full bg-[radial-gradient(circle,rgba(79,184,178,0.32),transparent_66%)]" />
        <div className="pointer-events-none absolute -bottom-20 -right-20 h-56 w-56 rounded-full bg-[radial-gradient(circle,rgba(47,106,74,0.18),transparent_66%)]" />
        <p className="island-kicker mb-3">Blog</p>
        <h1 className="display-title mb-5 max-w-3xl text-4xl leading-[1.02] font-bold tracking-tight text-[var(--sea-ink)] sm:text-6xl">
          Latest Posts
        </h1>
        <p className="mb-8 max-w-2xl text-base text-[var(--sea-ink-soft)] sm:text-lg">
          Thoughts, tutorials, and updates from the team.
        </p>
      </section>

      <section className="mt-8">
        {posts.length === 0 ? (
          <div className="island-shell rounded-2xl p-8 text-center">
            <p className="text-[var(--sea-ink-soft)] text-lg">No posts yet. Check back soon!</p>
          </div>
        ) : (
          <ul className="m-0 list-none space-y-4 p-0">
            {posts.map((post, index) => (
              <li
                key={post.id}
                className="rise-in"
                style={{ animationDelay: `${index * 90 + 80}ms` }}
              >
                <Link
                  to="/posts/$postId"
                  params={{ postId: String(post.id) }}
                  className="island-shell block rounded-2xl p-6 no-underline transition hover:-translate-y-0.5 hover:border-[color-mix(in_oklab,var(--lagoon-deep)_35%,var(--line))]"
                >
                  <h2 className="m-0 mb-2 text-xl font-bold text-[var(--sea-ink)]">
                    {post.title}
                  </h2>
                  <p className="m-0 text-sm text-[var(--sea-ink-soft)]">
                    Post #{post.id}
                  </p>
                </Link>
              </li>
            ))}
          </ul>
        )}
      </section>
    </main>
  )
}

import { createFileRoute, Link, notFound } from '@tanstack/react-router'
import { marked } from 'marked'
import { getPostById } from '../../server-functions/posts'

export const Route = createFileRoute('/posts/$postId')({
  loader: async ({ params }) => {
    const postId = Number(params.postId)
    if (isNaN(postId)) {
      throw notFound()
    }
    const post = await getPostById({ data: postId })
    if (!post) {
      throw notFound()
    }
    const htmlContent = await marked.parse(post.content)
    return { post, htmlContent }
  },
  component: PostDetail,
  notFoundComponent: PostNotFound,
})

function PostDetail() {
  const { post, htmlContent } = Route.useLoaderData()

  return (
    <main className="page-wrap px-4 pb-8 pt-14">
      <Link
        to="/"
        className="mb-6 inline-flex items-center gap-1 text-sm font-semibold text-[var(--lagoon-deep)] no-underline hover:underline"
      >
        ← Back to all posts
      </Link>

      <article className="island-shell rise-in rounded-[2rem] px-6 py-10 sm:px-10 sm:py-14">
        <p className="island-kicker mb-3">Post #{post.id}</p>
        <h1 className="display-title mb-8 text-4xl leading-[1.02] font-bold tracking-tight text-[var(--sea-ink)] sm:text-6xl">
          {post.title}
